func flattenSlo(ctx context.Context, p path.Path, v *slos_service.Slo, prior *SloModel, diags *diag.Diagnostics) *SloModel {
	if v == nil {
		return nil
	}
	out := &SloModel{}
	out.Sli = flattenSloSli(ctx, p.AtName("sli"), v, diags)
	out.ApmSliMetadata = types.ObjectNull(apmSliAttrTypes())
	if nested := flattenApmSli(ctx, p.AtName("apm_sli_metadata"), v.ApmSliMetadata, diags); nested != nil {
		value, valueDiags := types.ObjectValueFrom(ctx, apmSliAttrTypes(), *nested)
		diags.Append(valueDiags...)
		out.ApmSliMetadata = value
	}
	out.Description = types.StringPointerValue(v.Description)
	if out.Description.ValueString() == "" {
		out.Description = types.StringNull()
		// A configured "" and an omitted value both read back as "". The prior
		// is the plan or the state, so a configured empty string stays "".
		if prior != nil && !prior.Description.IsNull() && !prior.Description.IsUnknown() && prior.Description.ValueString() == "" {
			out.Description = types.StringValue("")
		}
	}
	out.Grouping = types.ObjectNull(v1GroupingAttrTypes())
	if nested := flattenV1Grouping(ctx, p.AtName("grouping"), v.Grouping, diags); nested != nil {
		value, valueDiags := types.ObjectValueFrom(ctx, v1GroupingAttrTypes(), *nested)
		diags.Append(valueDiags...)
		out.Grouping = value
	}
	out.Id = types.StringPointerValue(v.Id)
	out.Labels = flattenStringMap(ctx, v.Labels, diags)
	out.Name = types.StringPointerValue(v.Name)
	out.OwnershipTags = flattenSloOwnershipTags(ctx, p.AtName("ownership_tags"), v.OwnershipTags, diags)
	out.ProductType = flattenEnumMapped(p.AtName("product_type"), v.ProductType, sloProductTypeFromAPI, diags)
	out.Window = flattenSloWindow(ctx, p.AtName("window"), v, diags)
	out.TargetThresholdPercentage = types.Float32PointerValue(v.TargetThresholdPercentage)
	return out
}

